<script setup lang="ts">import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{useClassicGame}from'../composables/useClassicGame';import{useI18n,locale}from'../i18n';import{player}from'../stores';import{shareText}from'../utils';const g=useClassicGame(),{t}=useI18n(),router=useRouter(),menu=ref(false);onMounted(g.begin);async function share(){await shareText(`FLAG STREAK 🌍\n🔥 ${g.score.value} ${t.value('flags')}\n🏆 ${t.value('record')}: ${player.best}\n`)}function quit(){if(confirm(t.value('quit')))router.push('/home')}</script>
<template><section class="screen game" :class="g.status.value"><div v-if="g.status.value==='countdown'" class="countdown">{{g.countdown.value||'GO!'}}</div><template v-else-if="g.status.value!=='gameOver'"><header class="game-head"><strong>🔥 {{g.score.value}}</strong><button class="icon-btn" @click="menu=!menu" aria-label="Menu">Ⅱ</button><strong>🏆 {{player.best}}</strong></header><div class="timer"><span :style="{width:g.progress.value+'%'}"></span><b>{{g.time.value.toString().padStart(2,'0')}}</b></div><div v-if="g.question.value" class="question"><div class="flag" role="img" :aria-label="t('which')">{{g.question.value.country.flagAsset}}</div><h2>{{t('which')}}</h2><div class="answers"><button v-for="a in g.question.value.answers" :key="a.code" :disabled="g.status.value!=='playing'" :class="{chosen:g.selected.value===a.code,correct:g.status.value!=='playing'&&a.code===g.question.value.country.code,wrong:g.selected.value===a.code&&a.code!==g.question.value.country.code}" @click="g.answer(a)">{{a.names[locale]}}</button></div></div><div v-if="menu" class="modal"><div><h2>{{t('pause')}}</h2><button class="primary" @click="menu=false">{{t('resume')}}</button><button @click="quit">{{t('newGame')}}</button><button @click="router.push('/home')">{{t('home')}}</button></div></div></template><div v-else class="result"><div class="burst">{{g.isRecord.value?'🏆':'💥'}}</div><h1>{{g.isRecord.value?t('newRecord'):t('gameOver')}}</h1><p>{{t('answerWas')}}</p><div class="result-flag">{{g.question.value?.country.flagAsset}}</div><strong>{{g.question.value?.country.names[locale]}}</strong><div class="result-stats"><span>{{t('score')}}<b>{{g.score.value}}</b></span><span>{{t('record')}}<b>{{player.best}}</b></span></div><button class="primary" @click="g.begin">{{t('replay')}}</button><button @click="router.push('/home')">{{t('newGame')}}</button><button class="text-btn" @click="share">↗ {{t('share')}}</button></div></section></template>
